; MAP-DATA BANK  —  bank 40 ($28):  compressed TILEMAPS + TILESETS (32 blocks)
; ############################################################################
; NOT code (old 'function table' = the LZ tile-block POINTER TABLE; the payload
; disassembled as instructions is garbage). Overworld/interior MAP data as LZ
; blocks (TileLoad $18A2). Block kinds (decoded):
;   TILESET  2048 B = 128 tiles -> VRAM $9000   (16 blocks)
;   TILEMAP   512 B = 32x16 tile numbers -> WRAM $C300   (0 blocks)
; A room's tilemap {bank,block} = bank11 $4239; its tileset {bank,block} = ROM0
; $2AAC[wAreaID] (same bank). Compressed payload is emitted as db (reassembles
; BYTE-EXACT); decompressed grids/tiles are commented reference below.
; ############################################################################

SECTION "Bank 40", ROMX[$4000], BANK[40]

